    n, e = int(fields["n"], 16), int(fields["e"], 16)
    size = (n.bit_length() + 7) // 8
    if len(signature) != size:
        return False
    return pow(int.from_bytes(signature, "big"), e, n) == _pad(hashlib.sha256(signing_input).digest(), size)


